import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Touch } from '../types'

const PANE = 'touched'
const EDITED = '#d97757'
const files = atom({ plugin: 'touched', key: 'files' } as const, [])

const bump = (list: Touch[], path: string, kind: 'reads' | 'edits'): Touch[] => {
  const found = list.some(one => one.path === path)
  const base = found ? list : [...list, { path, reads: 0, edits: 0 }]

  return base.map(one => (one.path === path ? { ...one, [kind]: one[kind] + 1 } : one))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'touched',
      description: 'Show files Claude has read or edited this session',
    })

    return next(e)
  })

  on('command.run', { command: 'touched' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Touched files' })

    return { text: 'Touched files pane opened.' }
  })

  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    await update($, files, list => bump(list, e.file_path, 'reads'))

    return next(e)
  })

  on('tool.call', { tool: 'Edit' }, async ($, e, next) => {
    await update($, files, list => bump(list, e.file_path, 'edits'))

    return next(e)
  })

  on('tool.call', { tool: 'Write' }, async ($, e, next) => {
    await update($, files, list => bump(list, e.file_path, 'edits'))

    return next(e)
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const list = await read($, files)
    const root = (await $.session.cwd()).replace(/\/$/, '') + '/'
    const shown = (path: string) => (path.startsWith(root) ? path.slice(root.length) : path)
    const room = Math.max(1, (e.viewport?.rows ?? 24) - 5)
    const sorted = [...list].sort((a, b) => b.reads + b.edits - (a.reads + a.edits))

    return (
      <Box flexDirection="column">
        {sorted.length === 0 && <Text dimColor>No files touched yet.</Text>}
        {sorted.slice(0, room).map(one => (
          <Text color={one.edits > 0 ? EDITED : undefined}>
            {String(one.reads + one.edits).padStart(3)}x {shown(one.path)}
            <Text dimColor>
              {' '}
              ({one.reads} read, {one.edits} edit)
            </Text>
          </Text>
        ))}
        {sorted.length > room && <Text dimColor>+{sorted.length - room} more</Text>}
      </Box>
    )
  })
}

